/// <summary>
/// MPJ_28157_NDCAndInternalCrossDock
/// </summary>
public void updateQueryBuild()
{
    next updateQueryBuild();
    if(this.isInBatch && this.lateSelection())
        
    {             
        Query                   metQueryStd = new Query(chooseLines.query());
        QueryBuildDataSource    metQbdsStd  = metQueryStd.dataSourceTable(tableNum(salesTable)).addDataSource(tableNum(METSalesWarehouseDelayView));
        metQbdsStd.relations(true);
        metQbdsStd.joinMode(JoinMode::InnerJoin);
        metQbdsStd.fetchMode(QueryFetchMode::One2One);
        metQbdsStd.addLink(fieldNum(SalesTable,SalesId),fieldNum(METSalesWarehouseDelayView,Salesid));
        QueryBuildRange metQbrStd           = metQbdsStd.addRange(fieldNum(METSalesWarehouseDelayView, IsSOValidForInvoicing));
        metQbrStd.value(queryValue(NoYes::Yes));
        metQbrStd.status(RangeStatus::Hidden);
        chooseLines.query(metQueryStd);           
    }        
}
